346	// DeleteNodes deletes the nodes from the group.
347	func (ng *AwsNodeGroup) DeleteNodes(ctx context.Context, nodes []*apiv1.Node) error {
348		size := ng.asg.curSize
349		if int(size) <= ng.MinSize(context.TODO()) {
350			return fmt.Errorf("min size reached, nodes will not be deleted")
351		}
352		refs := make([]*AwsInstanceRef, 0, len(nodes))
353		for _, node := range nodes {
354			belongs, err := ng.Belongs(node)
355			if err != nil {
356				return err
357			}
358			if !belongs {
359				return fmt.Errorf("%s belongs to a different asg than %s", node.Name, ng.Id())
360			}
361			awsref, err := AwsRefFromProviderId(node.Spec.ProviderID)
362			if err != nil {
363				return err
364			}
365			refs = append(refs, awsref)
366		}
367		return ng.awsManager.DeleteInstances(refs)
368	}
