385	// Nodes returns a list of all nodes that belong to this node group.
386	func (ng *AwsNodeGroup) Nodes(ctx context.Context) ([]cloudprovider.Instance, error) {
387		asgNodes, err := ng.awsManager.GetAsgNodes(ng.asg.AwsRef)
388		if err != nil {
389			return nil, err
390		}
391	
392		instances := make([]cloudprovider.Instance, len(asgNodes))
393	
394		for i, asgNode := range asgNodes {
395			var status *cloudprovider.InstanceStatus
396			instanceStatusString, err := ng.awsManager.GetInstanceStatus(asgNode)
397			if err != nil {
398				klog.V(4).Infof("Could not get instance status, continuing anyways: %v", err)
399			} else if instanceStatusString != nil && *instanceStatusString == placeholderUnfulfillableStatus {
400				status = &cloudprovider.InstanceStatus{
401					State: cloudprovider.InstanceCreating,
402					ErrorInfo: &cloudprovider.InstanceErrorInfo{
403						ErrorClass:   cloudprovider.OutOfResourcesErrorClass,
404						ErrorCode:    placeholderUnfulfillableStatus,
405						ErrorMessage: "AWS cannot provision any more instances for this node group",
406					},
407				}
408			}
409			instances[i] = cloudprovider.Instance{
410				Id:     asgNode.ProviderID,
411				Status: status,
412			}
413		}
414		return instances, nil
415	}
