436	// BuildAWS builds AWS cloud provider, manager etc.
437	func BuildAWS(opts *coreoptions.AutoscalerOptions, do cloudprovider.NodeGroupDiscoveryOptions, rl *cloudprovider.ResourceLimiter) cloudprovider.CloudProvider {
438		var cfg io.ReadCloser
439		if opts.CloudConfig != "" {
440			var err error
441			cfg, err = os.Open(opts.CloudConfig)
442			if err != nil {
443				klog.Fatalf("Couldn't open cloud provider configuration %s: %#v", opts.CloudConfig, err)
444			}
445			defer cfg.Close()
446		}
447	
448		sdkProvider, err := createAWSSDKProvider(cfg)
449		if err != nil {
450			klog.Fatalf("Failed to create AWS SDK Provider: %v", err)
451		}
452	
453		// Generate EC2 list
454		instanceTypes, lastUpdateTime := GetStaticEC2InstanceTypes()
455		if opts.AWSUseStaticInstanceList {
456			klog.Warningf("Using static EC2 Instance Types, this list could be outdated. Last update time: %s", lastUpdateTime)
457		} else {
458			generatedInstanceTypes, err := GenerateEC2InstanceTypes(sdkProvider.cfg)
459			if err != nil {
460				klog.Errorf("Failed to generate AWS EC2 Instance Types: %v, falling back to static list with last update time: %s", err, lastUpdateTime)
461			}
462			if generatedInstanceTypes == nil {
463				generatedInstanceTypes = map[string]*InstanceType{}
464			}
465			// fallback on the static list if we miss any instance types in the generated output
466			// credits to: https://github.com/lyft/cni-ipvlan-vpc-k8s/pull/80
467			for k, v := range instanceTypes {
468				_, ok := generatedInstanceTypes[k]
469				if ok {
470					continue
471				}
472				klog.Infof("Using static instance type %s", k)
473				generatedInstanceTypes[k] = v
474			}
475			instanceTypes = generatedInstanceTypes
476	
477			keys := make([]string, 0, len(instanceTypes))
478			for key := range instanceTypes {
479				keys = append(keys, key)
480			}
481	
482			klog.Infof("Successfully load %d EC2 Instance Types %s", len(keys), keys)
483		}
484	
485		manager, err := CreateAwsManager(sdkProvider, do, instanceTypes)
486		if err != nil {
487			klog.Fatalf("Failed to create AWS Manager: %v", err)
488		}
489	
490		provider, err := BuildAwsCloudProvider(manager, rl)
491		if err != nil {
492			klog.Fatalf("Failed to create AWS cloud provider: %v", err)
493		}
494		RegisterMetrics()
495	
496		// Configure AWS specific processors
497		if opts.Processors != nil {
498			opts.Processors.TemplateNodeInfoProvider = nodeinfosprovider.NewAsgTagResourceNodeInfoProvider(&opts.AutoscalingOptions.NodeInfoCacheExpireTime, opts.AutoscalingOptions.ForceDaemonSets)
499			opts.Processors.NodeGroupSetProcessor = &nodegroupset.BalancingNodeGroupSetProcessor{
500				Comparator: nodegroupset.CreateAwsNodeInfoComparator(opts.AutoscalingOptions.BalancingExtraIgnoredLabels, opts.AutoscalingOptions.NodeGroupSetRatios),
501			}
502		}
503	
504		return provider
505	}

